/*==============================================================================
  VIDÉO 19 : ATELIER PRATIQUE, LA BOUTIQUE DE A À Z
  Script 05 : jeu d'essai VOLUMINEUX
  ------------------------------------------------------------------------------
  Ce script ne contient pas des millions d'INSERT : il GÉNÈRE les données côté
  serveur, en quelques minutes, à partir de vraies listes embarquées :
    - les 18 régions et 101 départements officiels,
    - ~10 000 communes réelles (plus de 1 000 habitants) avec leur code postal,
      leurs coordonnées GPS et leur population (source : geo.api.gouv.fr),
    - des prénoms, des noms de famille, des noms de rue courants.
  Les clients sont répartis au prorata de la population : beaucoup de
  Parisiens, de Lyonnais, de Niortais... comme dans la vraie vie.

  Volumes par défaut (paramètres en section 0) :
    Produits        ~   2 000
    Clients         ~ 300 000
    Commandes       ~ 1 300 000
    Lignes          ~ 2 700 000
  Durée indicative : 1 à 3 minutes selon la machine.

  Profils de clients générés VOLONTAIREMENT pour les démos :
    - ~78 % de clients actifs,
    - ~10 % de clients « dormants » : dernière commande il y a plus de 3 ans,
    - ~12 % de clients qui n'ont jamais commandé (dont beaucoup inscrits il y a
      plus de 3 ans),
    - ~2 % de clients supprimés logiquement (colonne Suppression renseignée),
      certains depuis plus de 3 mois, d'autres très récemment.
  Plus 6 clients « témoins » aux identifiants fixes (1 à 6), utilisés dans les démos.

  Prérequis : SQL Server 2022 ou plus (fonctions GENERATE_SERIES et GREATEST).
  Note : les tables temporaires vivent dans tempdb, dont la collation est celle
  du SERVEUR. On précise COLLATE DATABASE_DEFAULT sur leurs colonnes texte pour
  éviter les conflits de collation avec notre base en French_100_CI_AS.
  À lancer HORS CAMÉRA, une seule fois, juste après les scripts 01 à 04.
==============================================================================*/
USE Boutique;
GO
SET NOCOUNT ON;
GO

/*==============================================================================
  0. PARAMÈTRES ET PRÉPARATION
==============================================================================*/
IF EXISTS (SELECT 1 FROM ventes.Client) OR EXISTS (SELECT 1 FROM ref.Region)
BEGIN
    RAISERROR(N'La base contient déjà des données : repartez des scripts 01 à 04.', 16, 1);
    SET NOEXEC ON;   -- on n'exécute plus rien jusqu'à la fin du script
END
GO

DROP TABLE IF EXISTS #Parametres;
CREATE TABLE #Parametres
(
    NbClients     INT          NOT NULL,
    NbProduits    INT          NOT NULL,
    DebutHistorique DATETIME2(0) NOT NULL,   -- date de la toute première inscription
    Maintenant    DATETIME2(0) NOT NULL
);
INSERT INTO #Parametres
VALUES (300000,                                                  -- clients
        2000,                                                    -- produits
        DATEFROMPARTS(YEAR(SYSDATETIME()) - 10, 1, 1),           -- historique de 10 ans
        SYSDATETIME());
GO

-- Pendant le chargement massif, on passe temporairement en récupération SIMPLE :
-- le journal ne gonfle pas de plusieurs Go. On repasse en FULL à la fin.
ALTER DATABASE Boutique SET RECOVERY SIMPLE;
GO

