/*==============================================================================
  2. COMMUNES RÉELLES (table temporaire, sert uniquement à générer les clients)
  Une ligne par couple commune / code postal, avec la population.
==============================================================================*/
DROP TABLE IF EXISTS #Commune;
CREATE TABLE #Commune
(
    IdCommune       INT            IDENTITY(1,1) NOT NULL,
    CodeInsee       CHAR(5) COLLATE DATABASE_DEFAULT        NOT NULL,
    Nom             NVARCHAR(100) COLLATE DATABASE_DEFAULT  NOT NULL,
    CodePostal      CHAR(5) COLLATE DATABASE_DEFAULT        NOT NULL,
    CodeDepartement VARCHAR(3) COLLATE DATABASE_DEFAULT     NOT NULL,
    Latitude        DECIMAL(9,6)   NOT NULL,
    Longitude       DECIMAL(9,6)   NOT NULL,
    Population      INT            NOT NULL,
    CumulDebut      BIGINT         NULL      -- pour le tirage au sort pondéré
);

