-- Tirage pondéré par la population : chaque commune occupe une « tranche »
-- proportionnelle à son nombre d'habitants sur une grande règle graduée.
WITH c AS
(
    SELECT IdCommune,
           SUM(CAST(Population AS BIGINT)) OVER (ORDER BY IdCommune ROWS UNBOUNDED PRECEDING) - Population AS Debut
    FROM #Commune
)
UPDATE cm SET CumulDebut = c.Debut
FROM #Commune cm INNER JOIN c ON c.IdCommune = cm.IdCommune;

CREATE UNIQUE CLUSTERED INDEX CX_Commune_Cumul ON #Commune (CumulDebut, IdCommune);
GO

