DECLARE @NbProduits INT, @Debut DATETIME2(0);
SELECT @NbProduits = NbProduits, @Debut = DebutHistorique FROM #Parametres;

WITH Combinaisons AS
(
    SELECT  tp.*, m.Marque, g.Gamme,
            ROW_NUMBER() OVER (ORDER BY NEWID()) AS Tirage
    FROM    #TypeProduit tp
    CROSS JOIN (VALUES (N'Nova'),(N'Zentek'),(N'Orbis'),(N'Kalia'),(N'Vertigo'),
                       (N'Lumio'),(N'Axion'),(N'Stellar'),(N'Pixa'),(N'Brio')) m (Marque)
    CROSS JOIN (VALUES (N'Essentiel'),(N'Plus'),(N'Pro'),(N'Max'),(N'Lite'),(N'Origine')) g (Gamme)
)
INSERT INTO ventes.Produit (Reference, Nom, IdCategorie, PrixHT, TauxTVA, Stock, Actif, DateCreation)
SELECT  'PRD-' + RIGHT('000000' + CAST(ROW_NUMBER() OVER (ORDER BY c.Tirage) AS VARCHAR(6)), 6),
        c.TypeProduit + N' ' + c.Marque + N' ' + c.Gamme,
        cat.IdCategorie,
        FLOOR(c.PrixMin + (c.PrixMax - c.PrixMin) * RAND(CHECKSUM(NEWID()))) + 0.99,
        c.TauxTVA,
        ABS(CHECKSUM(NEWID())) % 500,
        CASE WHEN ABS(CHECKSUM(NEWID())) % 100 < 3 THEN 0 ELSE 1 END,
        DATEADD(DAY, ABS(CHECKSUM(NEWID())) % 365, @Debut)
FROM        Combinaisons      c
INNER JOIN  ventes.Categorie  cat ON cat.Libelle = c.Categorie
WHERE   c.Tirage <= @NbProduits
ORDER BY c.Tirage;
GO

