-- Leurs commandes (dates relatives à aujourd'hui).
DROP TABLE IF EXISTS #CmdTemoin;
CREATE TABLE #CmdTemoin (IdClient INT, DateCommande DATETIME2(0), Statut VARCHAR(12) COLLATE DATABASE_DEFAULT, Suppression DATETIME2(0));
INSERT INTO #CmdTemoin VALUES
(1, DATEADD(DAY,  -400, @Maintenant), 'LIVREE',   NULL),
(1, DATEADD(DAY,   -95, @Maintenant), 'LIVREE',   NULL),
(1, DATEADD(DAY,    -3, @Maintenant), 'EXPEDIEE', NULL),
(2, DATEADD(DAY,  -700, @Maintenant), 'LIVREE',   NULL),
(2, DATEADD(DAY,   -30, @Maintenant), 'LIVREE',   NULL),
(3, DATEADD(DAY, -2500, @Maintenant), 'LIVREE',   NULL),
(3, DATEADD(DAY, -1460, @Maintenant), 'LIVREE',   NULL),
(5, DATEADD(DAY,  -500, @Maintenant), 'LIVREE',   DATEADD(MONTH, -6, @Maintenant)),
(6, DATEADD(DAY,  -200, @Maintenant), 'LIVREE',   DATEADD(DAY,  -15, @Maintenant));

INSERT INTO ventes.Commande (IdClient, DateCommande, Statut, Suppression)
SELECT IdClient, DateCommande, Statut, Suppression FROM #CmdTemoin ORDER BY DateCommande;

-- Deux lignes par commande témoin, sur des produits actifs pris au hasard.
INSERT INTO ventes.LigneCommande (IdCommande, NumeroLigne, IdProduit, Quantite, PrixUnitaireHT, TauxTVA)
SELECT  c.IdCommande, n.value, p.IdProduit, 1 + n.value % 2, p.PrixHT, p.TauxTVA
FROM        ventes.Commande c
CROSS JOIN  GENERATE_SERIES(1, 2) n
CROSS APPLY (SELECT TOP (1) IdProduit, PrixHT, TauxTVA
             FROM ventes.Produit
             WHERE Actif = 1 AND IdProduit % 7 = (c.IdCommande + n.value) % 7
             ORDER BY IdProduit) p;
GO

/*==============================================================================
  6. LES CLIENTS GÉNÉRÉS
  Profil : A = actif, D = dormant (plus de commande depuis 3 ans),
           J = jamais commandé.
==============================================================================*/
DECLARE @NbClients INT, @Debut DATETIME2(0), @Maintenant DATETIME2(0);
SELECT @NbClients = NbClients, @Debut = DebutHistorique, @Maintenant = Maintenant FROM #Parametres;

DECLARE @PopTotale BIGINT = (SELECT SUM(CAST(Population AS BIGINT)) FROM #Commune);
DECLARE @NbPrenoms INT = (SELECT COUNT(*) FROM #Prenom),
        @NbNoms    INT = (SELECT COUNT(*) FROM #Nom),
        @NbVoies   INT = (SELECT COUNT(*) FROM #Voie),
        @NbDomaines INT = (SELECT COUNT(*) FROM #Domaine);
DECLARE @LimiteDormant DATETIME2(0) = DATEADD(YEAR, -4, @Maintenant);   -- les dormants sont inscrits depuis au moins 4 ans
DECLARE @Il3Ans        DATETIME2(0) = DATEADD(DAY, -1, DATEADD(YEAR, -3, @Maintenant));

DROP TABLE IF EXISTS #ClientGen;
CREATE TABLE #ClientGen
(
    n             INT            NOT NULL PRIMARY KEY,
    Profil        CHAR(1) COLLATE DATABASE_DEFAULT        NOT NULL,
    Prenom        NVARCHAR(40) COLLATE DATABASE_DEFAULT   NOT NULL,
    Nom           NVARCHAR(40) COLLATE DATABASE_DEFAULT   NOT NULL,
    Email         NVARCHAR(160) COLLATE DATABASE_DEFAULT  NOT NULL,
    Telephone     VARCHAR(20) COLLATE DATABASE_DEFAULT    NULL,
    Adresse       NVARCHAR(200) COLLATE DATABASE_DEFAULT  NOT NULL,
    CodePostal    CHAR(5) COLLATE DATABASE_DEFAULT        NOT NULL,
    Ville         NVARCHAR(100) COLLATE DATABASE_DEFAULT  NOT NULL,
    CodeDepartement VARCHAR(3) COLLATE DATABASE_DEFAULT   NOT NULL,
    Latitude      DECIMAL(9,6)   NOT NULL,
    Longitude     DECIMAL(9,6)   NOT NULL,
    DateCreation  DATETIME2(0)   NOT NULL,
    NbCommandes   INT            NOT NULL,
    FenetreDebut  DATETIME2(0)   NULL,
    FenetreFin    DATETIME2(0)   NULL,
    IdClient      INT            NULL
);

-- On matérialise d'abord les tirages au sort dans une table temporaire :
-- NEWID() est réévalué à chaque utilisation, on fige donc les valeurs une fois pour toutes.
DROP TABLE IF EXISTS #Tirage;
    SELECT  s.value AS n,
            RAND(CHECKSUM(NEWID()))                                   AS rProfil,
            RAND(CHECKSUM(NEWID()))                                   AS rDate,
            RAND(CHECKSUM(NEWID()))                                   AS rNbCmd,
            CAST(RAND(CHECKSUM(NEWID())) * @PopTotale AS BIGINT)      AS rCommune,
            ABS(CHECKSUM(NEWID())) % @NbPrenoms + 1                   AS iPrenom,
            ABS(CHECKSUM(NEWID())) % @NbNoms + 1                      AS iNom,
            ABS(CHECKSUM(NEWID())) % @NbVoies + 1                     AS iVoie,
            ABS(CHECKSUM(NEWID())) % @NbDomaines + 1                  AS iDomaine,
            ABS(CHECKSUM(NEWID())) % 120 + 1                          AS NumeroVoie,
            ABS(CHECKSUM(NEWID())) % 100000000                        AS NumTel,
            ABS(CHECKSUM(NEWID())) % 100                              AS rTel,
            (RAND(CHECKSUM(NEWID())) - 0.5) / 50                      AS DecalageLat,
            (RAND(CHECKSUM(NEWID())) - 0.5) / 50                      AS DecalageLon
    INTO    #Tirage
    FROM    GENERATE_SERIES(1, @NbClients) s;

WITH AvecProfil AS
(
    SELECT  t.*,
            CASE WHEN t.rProfil < 0.12 THEN 'J'
                 WHEN t.rProfil < 0.22 THEN 'D'
                 ELSE 'A' END AS Profil
    FROM #Tirage t
)
INSERT INTO #ClientGen (n, Profil, Prenom, Nom, Email, Telephone, Adresse, CodePostal, Ville,
                        CodeDepartement, Latitude, Longitude, DateCreation, NbCommandes)
SELECT  a.n,
        a.Profil,
        pr.Valeur,
        nm.Valeur,
        -- email sans accents ni espaces : prenom.nom.N@domaine
        REPLACE(TRANSLATE(LOWER(pr.Valeur + N'.' + nm.Valeur),
                          N'àâäéèêëîïôöùûüçÿ'' ', N'aaaeeeeiioouuucy--'), N'-', N'')
            + N'.' + CAST(a.n AS NVARCHAR(10)) + N'@' + d.Valeur,
        CASE WHEN a.rTel < 20 THEN NULL
             ELSE '0' + CASE WHEN a.rTel % 2 = 0 THEN '6' ELSE '7' END
                      + RIGHT('00000000' + CAST(a.NumTel AS VARCHAR(8)), 8) END,
        CAST(a.NumeroVoie AS NVARCHAR(5)) + N' ' + v.Valeur,
        cm.CodePostal,
        cm.Nom,
        cm.CodeDepartement,
        CAST(cm.Latitude  + a.DecalageLat AS DECIMAL(9,6)),
        CAST(cm.Longitude + a.DecalageLon AS DECIMAL(9,6)),
        CASE a.Profil
            WHEN 'D' THEN DATEADD(SECOND, CAST(a.rDate * DATEDIFF_BIG(SECOND, @Debut, @LimiteDormant) AS BIGINT), @Debut)
            ELSE          DATEADD(SECOND, CAST(a.rDate * DATEDIFF_BIG(SECOND, @Debut, DATEADD(DAY, -7, @Maintenant)) AS BIGINT), @Debut)
        END,
        CASE a.Profil
            WHEN 'J' THEN 0
            WHEN 'D' THEN 1 + CAST(4 * a.rNbCmd AS INT)                    -- 1 à 4 commandes
            ELSE          1 + CAST(14 * POWER(a.rNbCmd, 2) AS INT)         -- 1 à 14, surtout peu
        END
FROM        AvecProfil a
INNER JOIN  #Prenom  pr ON pr.Id = a.iPrenom
INNER JOIN  #Nom     nm ON nm.Id = a.iNom
INNER JOIN  #Voie    v  ON v.Id  = a.iVoie
INNER JOIN  #Domaine d  ON d.Id  = a.iDomaine
CROSS APPLY (SELECT TOP (1) c.CodePostal, c.Nom, c.CodeDepartement, c.Latitude, c.Longitude
             FROM   #Commune c
             WHERE  c.CumulDebut <= a.rCommune
             ORDER BY c.CumulDebut DESC) cm;

-- Fenêtre de dates dans laquelle tombent les commandes du client.
UPDATE #ClientGen
SET FenetreDebut = DateCreation,
    FenetreFin   = CASE Profil WHEN 'D' THEN @Il3Ans ELSE @Maintenant END
WHERE NbCommandes > 0;

-- Insertion dans la vraie table, dans l'ordre chronologique d'inscription.
INSERT INTO ventes.Client WITH (TABLOCK)
       (Nom, Prenom, Email, Telephone, Adresse, CodePostal, Ville, CodeDepartement,
        Latitude, Longitude, DateCreation)
SELECT  Nom, Prenom, Email, Telephone, Adresse, CodePostal, Ville, CodeDepartement,
        Latitude, Longitude, DateCreation
FROM    #ClientGen
ORDER BY DateCreation;

-- On récupère l'identifiant attribué à chaque client (l'email est unique).
UPDATE g SET IdClient = c.IdClient
FROM #ClientGen g INNER JOIN ventes.Client c ON c.Email = g.Email;
GO

/*==============================================================================
  7. LES COMMANDES GÉNÉRÉES
==============================================================================*/
DECLARE @Maintenant DATETIME2(0) = (SELECT Maintenant FROM #Parametres);

DROP TABLE IF EXISTS #CmdGen;
CREATE TABLE #CmdGen (IdClient INT NOT NULL, DateCommande DATETIME2(0) NOT NULL, rStatut FLOAT NOT NULL);

DECLARE @Il3Ans DATETIME2(0) = DATEADD(YEAR, -3, @Maintenant);

-- Un client actif a forcément au moins une commande dans les 3 dernières années
-- (sa commande n°1 est tirée dans cette période), les autres sont libres.
INSERT INTO #CmdGen WITH (TABLOCK) (IdClient, DateCommande, rStatut)
SELECT  g.IdClient,
        DATEADD(SECOND,
                CAST(RAND(CHECKSUM(NEWID())) * DATEDIFF_BIG(SECOND, f.Debut, g.FenetreFin) AS BIGINT),
                f.Debut),
        RAND(CHECKSUM(NEWID()))
FROM        #ClientGen g
CROSS APPLY GENERATE_SERIES(1, g.NbCommandes) s
CROSS APPLY (SELECT CASE WHEN g.Profil = 'A' AND s.value = 1
                         THEN GREATEST(g.FenetreDebut, @Il3Ans)
                         ELSE g.FenetreDebut END AS Debut) f
WHERE   g.NbCommandes > 0;

-- Dans l'ordre chronologique : l'identifiant de commande suit le temps, comme en vrai.
INSERT INTO ventes.Commande WITH (TABLOCK) (IdClient, DateCommande, Statut)
SELECT  IdClient,
        DateCommande,
        CASE WHEN rStatut < 0.04                               THEN 'ANNULEE'
             WHEN DateCommande < DATEADD(DAY, -15, @Maintenant) THEN 'LIVREE'
             WHEN rStatut < 0.30                               THEN 'EN_ATTENTE'
             WHEN rStatut < 0.65                               THEN 'PAYEE'
             ELSE                                                   'EXPEDIEE' END
FROM    #CmdGen
ORDER BY DateCommande;
GO

/*==============================================================================
  8. LES LIGNES DE COMMANDE (la plus grosse table)
  1 à 5 lignes par commande (surtout 1 ou 2). Certains produits sont des
  « best-sellers », d'autres se vendent très peu : c'est ce déséquilibre qui
  rendra les démos de plans d'exécution intéressantes.
  Le prix payé suit une légère inflation : les vieilles commandes sont moins chères.
==============================================================================*/
DECLARE @NbProduits INT = (SELECT MAX(IdProduit) FROM ventes.Produit);
DECLARE @Debut DATETIME2(0), @Maintenant DATETIME2(0);
SELECT @Debut = DebutHistorique, @Maintenant = Maintenant FROM #Parametres;
DECLARE @Duree FLOAT = DATEDIFF(DAY, @Debut, @Maintenant);

DROP TABLE IF EXISTS #NbLignes;
SELECT  IdCommande, DateCommande,
        1 + CAST(5 * POWER(RAND(CHECKSUM(NEWID())), 2.5) AS INT) AS NbLignes
INTO    #NbLignes
FROM    ventes.Commande
WHERE   IdClient > 6;

DROP TABLE IF EXISTS #LigneGen;
CREATE TABLE #LigneGen (IdCommande INT, NumeroLigne SMALLINT, IdProduit INT, Quantite INT, DateCommande DATETIME2(0), rPrix FLOAT);

INSERT INTO #LigneGen WITH (TABLOCK)
SELECT  nl.IdCommande,
        s.value,
        1 + CAST((@NbProduits - 1) * POWER(RAND(CHECKSUM(NEWID())), 3) AS INT),
        CASE WHEN ABS(CHECKSUM(NEWID())) % 10 < 8 THEN 1 ELSE 2 + ABS(CHECKSUM(NEWID())) % 3 END,
        nl.DateCommande,
        RAND(CHECKSUM(NEWID()))
FROM        #NbLignes nl
CROSS APPLY GENERATE_SERIES(1, nl.NbLignes) s;

INSERT INTO ventes.LigneCommande WITH (TABLOCK)
       (IdCommande, NumeroLigne, IdProduit, Quantite, PrixUnitaireHT, TauxTVA)
SELECT  lg.IdCommande,
        lg.NumeroLigne,
        lg.IdProduit,
        lg.Quantite,
        CAST(p.PrixHT * (0.85 + 0.15 * DATEDIFF(DAY, @Debut, lg.DateCommande) / @Duree)
                      * (0.97 + 0.06 * lg.rPrix) AS DECIMAL(10,2)),
        p.TauxTVA
FROM        #LigneGen      lg
INNER JOIN  ventes.Produit p ON p.IdProduit = lg.IdProduit
ORDER BY lg.IdCommande, lg.NumeroLigne;
GO

/*==============================================================================
  9. SUPPRESSIONS LOGIQUES
  ~2 % des clients actifs ont demandé leur suppression : la date de suppression
  tombe entre leur dernière activité et aujourd'hui. Leurs commandes sont
  marquées avec la même date.
==============================================================================*/
DECLARE @Maintenant DATETIME2(0) = (SELECT Maintenant FROM #Parametres);

DROP TABLE IF EXISTS #Supprimes;
SELECT  c.IdClient,
        DATEADD(SECOND,
                CAST(RAND(CHECKSUM(NEWID())) * DATEDIFF_BIG(SECOND, d.DerniereActivite, @Maintenant) AS BIGINT),
                d.DerniereActivite) AS DateSuppression
INTO    #Supprimes
FROM        ventes.Client c
CROSS APPLY (SELECT GREATEST(c.DateCreation,
                             ISNULL((SELECT MAX(DateCommande) FROM ventes.Commande cm WHERE cm.IdClient = c.IdClient),
                                    c.DateCreation)) AS DerniereActivite) d
WHERE   c.IdClient > 6
  AND   c.IdClient % 50 = 0;          -- un client sur 50

UPDATE c SET Suppression = s.DateSuppression
FROM ventes.Client c INNER JOIN #Supprimes s ON s.IdClient = c.IdClient;

UPDATE cm SET Suppression = s.DateSuppression
FROM ventes.Commande cm INNER JOIN #Supprimes s ON s.IdClient = cm.IdClient;
GO

/*==============================================================================
  10. FIN : retour en récupération COMPLÈTE, statistiques, contrôle
==============================================================================*/
ALTER DATABASE Boutique SET RECOVERY FULL;
GO
UPDATE STATISTICS ventes.Client        WITH FULLSCAN;
UPDATE STATISTICS ventes.Commande      WITH FULLSCAN;
UPDATE STATISTICS ventes.LigneCommande WITH FULLSCAN;
UPDATE STATISTICS ventes.Produit       WITH FULLSCAN;
GO

SELECT 'Région'         AS Table_, COUNT(*) AS NbLignes FROM ref.Region
UNION ALL SELECT 'Département',        COUNT(*) FROM ref.Departement
UNION ALL SELECT 'Catégorie',          COUNT(*) FROM ventes.Categorie
UNION ALL SELECT 'Produit',            COUNT(*) FROM ventes.Produit
UNION ALL SELECT 'Client',             COUNT(*) FROM ventes.Client
UNION ALL SELECT 'Commande',           COUNT(*) FROM ventes.Commande
UNION ALL SELECT 'LigneCommande',      COUNT(*) FROM ventes.LigneCommande;

-- Les profils qui nous intéressent pour la suite de la démo.
DECLARE @Il3Ans DATETIME2(0) = DATEADD(YEAR, -3, SYSDATETIME()),
        @Il3Mois DATETIME2(0) = DATEADD(MONTH, -3, SYSDATETIME());
SELECT
    (SELECT COUNT(*) FROM ventes.Client c
     WHERE  c.Suppression IS NULL AND c.DateCreation < @Il3Ans
       AND  NOT EXISTS (SELECT 1 FROM ventes.Commande cm
                        WHERE cm.IdClient = c.IdClient AND cm.DateCommande >= @Il3Ans)) AS Inactifs_3ans_RGPD,
    (SELECT COUNT(*) FROM ventes.Client WHERE Suppression <  @Il3Mois)                AS Supprimes_plus_3_mois,
    (SELECT COUNT(*) FROM ventes.Client WHERE Suppression >= @Il3Mois)                AS Supprimes_recents;
GO

SET NOEXEC OFF;
GO
